const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],prefix=document.body.dataset.prefix||'',money=n=>'₹'+n.toLocaleString('en-IN');
let bag=new Map(),toastTimer,quantity=1;try{const saved=JSON.parse(localStorage.getItem('barkat-bag-v2')||'[]');for(const [id,n] of saved)if(products.some(p=>p.id===id)&&Number.isInteger(n)&&n>0&&n<=99)bag.set(id,n)}catch{}
function notify(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function productUrl(p){return prefix+(p.slug?'fragrances/'+p.slug+'.html':p.id==='kit'?'gifting.html':'vessels.html')}
function updateBag(){let total=0,count=0;$('#cart-items').innerHTML=[...bag].map(([id,n])=>{const p=products.find(p=>p.id===id);total+=p.price*n;count+=n;return `<article class="cart-item"><strong><a href="${productUrl(p)}">${p.name}</a></strong><div class="cart-item-bottom"><div class="quantity"><button data-qty="${id}" data-delta="-1" aria-label="Remove one ${p.name}">−</button><span>${n}</span><button data-qty="${id}" data-delta="1" aria-label="Add one ${p.name}" ${n===99?'disabled':''}>+</button></div><span>${money(p.price*n)}</span></div></article>`}).join('')||`<div class="empty-note"><p>Your bag is waiting for its first little ritual.</p><a class="btn outline" href="${prefix}fragrances.html">Explore fragrances ↗</a></div>`;$('#bag-count').textContent=count;$('#cart-total').textContent=money(total);try{localStorage.setItem('barkat-bag-v2',JSON.stringify([...bag]))}catch{}}
function addToBag(id,n=1){if(!products.some(p=>p.id===id))return;bag.set(id,Math.min(99,(bag.get(id)||0)+n));updateBag();notify('Added to your ritual.')}
function openDialog(id){$(id).showModal();document.body.style.overflow='hidden'}
$$('dialog').forEach(d=>{d.addEventListener('close',()=>{if(!document.querySelector('dialog[open]'))document.body.style.overflow=''});d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}})});
document.addEventListener('click',e=>{const add=e.target.closest('[data-add]');if(add)addToBag(add.dataset.add);if(e.target.closest('[data-open-cart]')){updateBag();openDialog('#cart-dialog')}if(e.target.closest('[data-close]'))e.target.closest('dialog').close();const qty=e.target.closest('[data-qty]');if(qty){const id=qty.dataset.qty,n=(bag.get(id)||0)+Number(qty.dataset.delta);n>0?bag.set(id,Math.min(n,99)):bag.delete(id);updateBag();(document.querySelector(`[data-qty="${id}"][data-delta="${qty.dataset.delta}"]`)||$('#cart-dialog [data-close]')).focus()}const quick=e.target.closest('[data-quick]');if(quick)showVessel(quick.dataset.quick);if(e.target.closest('[data-finder]')){finderStep();openDialog('#finder-dialog')}});
$('#menu-open').onclick=()=>openDialog('#menu-dialog');updateBag();window.addEventListener('storage',e=>{if(e.key==='barkat-bag-v2'){try{bag=new Map(JSON.parse(e.newValue||'[]').filter(([id,n])=>products.some(p=>p.id===id)&&Number.isInteger(n)&&n>0&&n<=99));updateBag()}catch{}}});
// Catalogue filtering and sorting, with shareable filter state.
if($('[data-catalog]')){const grid=$('#catalog-grid'),cards=[...grid.children],kind=$('[data-catalog]').dataset.catalog;let active='All';const params=new URLSearchParams(location.search);if($$('[data-filter]').some(b=>b.dataset.filter===params.get('family')))active=params.get('family');$('#catalog-search').value=params.get('q')||'';if(['featured','name','price-up','price-down'].includes(params.get('sort')))$('#catalog-sort').value=params.get('sort');function filter(sync=true){const q=$('#catalog-search').value.trim().toLowerCase(),sort=$('#catalog-sort').value;let visible=0;const sorted=[...cards].sort((a,b)=>sort==='name'?a.dataset.name.localeCompare(b.dataset.name):sort==='price-up'?Number(a.dataset.price)-Number(b.dataset.price):sort==='price-down'?Number(b.dataset.price)-Number(a.dataset.price):cards.indexOf(a)-cards.indexOf(b));sorted.forEach(c=>{c.hidden=!(active==='All'||c.dataset.family===active)||!c.dataset.name.toLowerCase().includes(q);if(!c.hidden)visible++;grid.append(c)});$$('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.filter===active)));$('#catalog-empty').hidden=visible>0;$('#result-count').textContent=visible+' '+(kind==='fragrances'?(visible===1?'fragrance':'fragrances'):(visible===1?'vessel':'vessels'));if(sync&&location.protocol!=='file:'){const u=new URL(location.href);active==='All'?u.searchParams.delete('family'):u.searchParams.set('family',active);q?u.searchParams.set('q',q):u.searchParams.delete('q');sort==='featured'?u.searchParams.delete('sort'):u.searchParams.set('sort',sort);history.replaceState(null,'',u)}}$$('[data-filter]').forEach(b=>b.onclick=()=>{active=b.dataset.filter;filter()});$('#catalog-search').addEventListener('input',()=>filter());$('#catalog-sort').onchange=()=>filter();$('#reset-filters').onclick=()=>{active='All';$('#catalog-search').value='';$('#catalog-sort').value='featured';filter();$('[data-filter="All"]').focus()};filter(false)}
// Product detail quantity and gallery.
if($('#product-add')){function refreshQuantity(){const p=products.find(p=>p.id===$('#product-add').dataset.productId);$('#product-quantity').value=quantity;$('#quantity-minus').disabled=quantity===1;$('#quantity-plus').disabled=quantity===99;$('#product-add').innerHTML='Add to ritual · '+money(p.price*quantity)+' <span>+</span>'}$('#quantity-minus').onclick=()=>{quantity=Math.max(1,quantity-1);refreshQuantity()};$('#quantity-plus').onclick=()=>{quantity=Math.min(99,quantity+1);refreshQuantity()};$('#product-add').onclick=()=>addToBag($('#product-add').dataset.productId,quantity);$$('[data-gallery]').forEach(b=>b.onclick=()=>{$$('[data-gallery]').forEach(t=>t.setAttribute('aria-pressed',String(t===b)));$('#pack-view').hidden=b.dataset.gallery!=='pack';$('#texture-view').hidden=b.dataset.gallery!=='texture'})}
function showVessel(id){const p=products.find(p=>p.id===id);$('#quick-heading').textContent=p.name;$('#quick-content').innerHTML=`<div class="quick-body"><p class="eyebrow">${p.finish}</p><h3>A place for your glow.</h3><p>${p.desc}</p><p class="quick-price">${money(p.price)}</p><p>Part of the Barkat vessel concept collection. Final photographs, dimensions and candle-use specifications will be added before launch.</p><button class="btn" data-add="${p.id}">Add vessel to ritual +</button><p class="note">Preview bag only. No order will be placed.</p><a class="pairing-link" href="${prefix}fragrances.html">Find a fragrance to pair with it <span>↗</span></a></div>`;openDialog('#quick-dialog')}
// A short, transparent finder based on the supplied fragrance notes.
let finderMood='';function finderStep(){const el=$('#finder-content');el.innerHTML='<div class="finder-step"><p class="eyebrow">1 OF 2 / YOUR MOMENT</p><h3>What kind of pause?</h3><div class="finder-options">'+['Slow mornings','A fresh start','Evening unwind'].map(m=>`<button data-mood="${m}">${m} <span aria-hidden="true">↗</span></button>`).join('')+'</div></div>';el.querySelectorAll('[data-mood]').forEach(b=>b.onclick=()=>{finderMood=b.dataset.mood;finderNotes()})}
function finderNotes(){const el=$('#finder-content');el.innerHTML='<div class="finder-step"><p class="eyebrow">2 OF 2 / YOUR NOTES</p><h3>What draws you in?</h3><div class="finder-options">'+['Warm & spiced','Fresh & bright','Floral & soft','Woody & grounded'].map((n,i)=>`<button data-note="${i}">${n}</button>`).join('')+'</div><button class="text-button finder-back" id="finder-back">← Change my moment</button></div>';$('#finder-back').onclick=finderStep;el.querySelectorAll('[data-note]').forEach(b=>b.onclick=()=>{const families=[['Warm'],['Fresh','Citrus'],['Floral','Fresh'],['Woody']][Number(b.dataset.note)];const matches=products.filter(p=>p.slug&&families.includes(p.family));const p=matches.find(p=>p.mood===finderMood)||matches[0];el.innerHTML=`<div class="finder-result"><p class="eyebrow">YOUR STARTING POINT</p><h3>${p.name}</h3><p>${p.notes.join(' · ')}</p><p>${p.story}</p><p class="note">Matched to your preferred scent family${p.mood===finderMood?' and moment':''}.</p><a class="btn" href="${productUrl(p)}">Explore this fragrance ↗</a><button class="text-button finder-back" id="finder-again">Try another mood</button></div>`;$('#finder-again').onclick=finderStep;el.querySelector('a').focus()})}

if(document.querySelector(".scene")){
const steps=[...document.querySelectorAll('.ritual-step')],scene=document.querySelector('.scene'),dots=document.querySelector('.step-dots'),reduced=matchMedia('(prefers-reduced-motion: reduce)');let currentStep=0,manualUntil=0;
steps.forEach((s,i)=>{const b=document.createElement('button');b.textContent=i+1;b.setAttribute('aria-label','Show step '+(i+1)+': '+s.querySelector('h3').textContent);b.onclick=()=>chooseStep(i);dots.append(b)});
let circles='';for(let row=0;row<12;row++){for(let col=0;col<24;col++){let x=171+col*6.9+(row%2)*3,y=235+row*6;circles+=`<circle class="${row<3?'falling':''}" cx="${x}" cy="${y}" r="${2.6+(col%3)*.2}" fill="${(row+col)%3===0?'#ffffff':'#f5f1e9'}" stroke="#d7ceca" stroke-width=".5" style="animation-delay:${col*.025}s"/>`}}document.querySelector('#pearls-diagram').innerHTML=circles;
function setStep(n){currentStep=Math.max(0,Math.min(4,n));scene.dataset.step=currentStep;steps.forEach((s,i)=>s.classList.toggle('active',i===currentStep));[...dots.children].forEach((d,i)=>{if(i===currentStep)d.setAttribute('aria-current','step');else d.removeAttribute('aria-current')});document.querySelector('#scene-title').textContent=steps[currentStep].querySelector('h3').textContent;document.querySelector('#scene-number').textContent='0'+(currentStep+1)+' / 05';document.querySelector('#step-back').disabled=currentStep===0;document.querySelector('#step-next').disabled=currentStep===4}
function chooseStep(n){setStep(n);manualUntil=Date.now()+1200;if(innerWidth>900&&!reduced.matches)steps[currentStep].scrollIntoView({block:'center',behavior:'smooth'})}
document.querySelector('#step-back').onclick=()=>chooseStep(currentStep-1);document.querySelector('#step-next').onclick=()=>chooseStep(currentStep+1);
const observer=new IntersectionObserver(entries=>{if(innerWidth<=900||reduced.matches||Date.now()<manualUntil)return;const visible=entries.filter(e=>e.isIntersecting);if(visible.length)setStep(Number(visible[0].target.dataset.step))},{rootMargin:'-30% 0px -35% 0px',threshold:0});steps.forEach(s=>observer.observe(s));setStep(0);
}

if(document.querySelector("#sand")){ // Marks gently settle.
const canvas=document.querySelector('#sand'),ctx=canvas.getContext('2d');let trails=[],drawing=false,frame=0,px=100,py=100,last=performance.now();function resizeSand(){const r=canvas.getBoundingClientRect(),d=devicePixelRatio||1;canvas.width=r.width*d;canvas.height=220*d;ctx.setTransform(d,0,0,d,0,0);paintSand(performance.now())}function paintSand(now){const w=canvas.clientWidth;ctx.fillStyle='#efdfc7';ctx.fillRect(0,0,w,220);for(let i=0;i<1400;i++){const x=(i*97.13)%w,y=(i*67.71)%220;ctx.fillStyle=i%2?'#c9b79855':'#fffaf288';ctx.fillRect(x,y,1,1)}trails=trails.filter(t=>now-t.time<4000);for(const t of trails){const a=Math.max(0,1-(now-t.time)/4000);ctx.fillStyle=`rgba(133,103,65,${a*.21})`;ctx.beginPath();ctx.ellipse(t.x,t.y,17,7,-.4,0,Math.PI*2);ctx.fill();ctx.strokeStyle=`rgba(255,252,234,${a*.6})`;ctx.beginPath();ctx.ellipse(t.x,t.y+3,17,7,-.4,0,Math.PI);ctx.stroke()}frame=0;if(trails.length)frame=requestAnimationFrame(paintSand)}function stamp(x,y){trails.push({x,y,time:performance.now()});if(!frame)frame=requestAnimationFrame(paintSand)}function locate(e){const r=canvas.getBoundingClientRect();return{x:e.clientX-r.left,y:e.clientY-r.top}}canvas.addEventListener('pointerdown',e=>{drawing=true;canvas.setPointerCapture(e.pointerId);const p=locate(e);px=p.x;py=p.y;stamp(px,py)});canvas.addEventListener('pointermove',e=>{if(!drawing)return;const p=locate(e),dist=Math.hypot(p.x-px,p.y-py),n=Math.max(1,Math.ceil(dist/5));for(let i=1;i<=n;i++)stamp(px+(p.x-px)*i/n,py+(p.y-py)*i/n);px=p.x;py=p.y});['pointerup','pointercancel'].forEach(ev=>canvas.addEventListener(ev,()=>drawing=false));function clearSand(){trails=[];if(frame)cancelAnimationFrame(frame);paintSand(performance.now())}document.querySelector('#sand-clear').onclick=clearSand;canvas.addEventListener('keydown',e=>{if(e.key.toLowerCase()==='c'){clearSand();return}if(!['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();px=Math.max(15,Math.min(canvas.clientWidth-15,px+(e.key==='ArrowRight'?12:e.key==='ArrowLeft'?-12:0)));py=Math.max(15,Math.min(205,py+(e.key==='ArrowDown'?12:e.key==='ArrowUp'?-12:0)));stamp(px,py)});new ResizeObserver(resizeSand).observe(canvas);
}

